export const ui={page:'mixer',serial:'',status:null,connected:false,busy:false,layer:null,savedLayer:null,liveLayer:null,apps:null,savedApps:null,appLive:null,tab:'actions',actionPage:0,button:0,channel:__tr('Music'),appPage:1,appEdit:null,adding:false,recording:false,undo:null,compare:false,stopped:false,lifeDraft:{},diagnostics:null,serviceError:'',actionsError:'',appsError:''};
let polling=false,timer,signature='',liveFeed,eventTimer,refreshPending=false;
const mixer=()=>ui.status?.mixers?.[ui.serial];
