function range(id,label,value,min,max,cmd,unit='',step=1){return field(id,`${label} · <output id="${id}-value">${value}${unit}</output>`,__tr`<input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" ${attrCommand(cmd)} data-unit="${esc(unit)}">`);}
