function distributionSettings(){return __tr`<section class="panel"><h2>Idioma</h2><label for="app-language">Idioma</label><select id="app-language"><option value="pt-PT" ${getLanguage()==='pt-PT'?'selected':''}>Português</option><option value="en" ${getLanguage()==='en'?'selected':''}>English</option></select><p class="note">Aplicação beta testada no GoXLR Mini. O GoXLR completo ainda não foi validado fisicamente.</p></section><section class="panel section"><h2>Atualizações da aplicação</h2><p id="update-status" role="status">${__tr('Versão')} 0.1.0-beta.2</p><div class="toolbar"><button data-check-update>Verificar atualizações</button><a href="https://github.com/Skolastico/SlopXLR/releases" target="_blank" rel="noopener noreferrer">Ver versões no GitHub</a><button data-install-update hidden>Instalar atualização</button></div></section><details class="panel section"><summary>Opções avançadas</summary><p><a href="/index.html">Interface anterior</a></p></details>`;}
export function renderSettings(){return baseSettings()+distributionSettings()+deviceSettings(mixer(),ui.status.files,ui.lifeDraft)+systemSettings(ui.status.config)+__tr`<section class="panel section"><h2>Encerrar aplicação</h2><p class="note">Encerra o serviço, incluindo as ações dos botões. O serviço executa as ações automáticas configuradas nesta página.</p><button data-stop-daemon>Encerrar serviço GoXLR</button></section>`+firmware(mixer(),ui.status,ui.serial);}
export function renderEffects(){return heading(__tr('Presets e processamento dos efeitos de voz.'))+effects(mixer(),ui.status.files);}
export function renderSampler(){return heading(isMini(mixer())?__tr('Soundboard por software para o Mini, com bancos virtuais e ações nos botões.'):__tr('Bancos, botões e biblioteca de áudio do sampler.'))+sampler(mixer(),ui.status.files,ui.savedLayer);}
export function renderProfiles(){return heading(__tr('Perfis do dispositivo, microfone e biblioteca de ficheiros.'))+profiles(mixer(),ui.status.files);}
const views={mixer:renderMixer,mic:renderMic,controls:renderControls,apps:renderApplications,routing:renderRouting,lighting:renderLighting,settings:renderSettings,diagnostics:renderDiagnostics,effects:renderEffects,sampler:renderSampler,profiles:renderProfiles};

function render(focus){if(ui.stopped){$('navigation').innerHTML='';$('device').disabled=true;$('profile').disabled=true;$('save-profile').disabled=true;$('runtime').textContent=__tr('Serviço encerrado');$('main').innerHTML=heading(__tr('Serviço encerrado.'))+__tr('<p class="empty">O áudio deixou de ser controlado por esta aplicação. Para voltar a usar, abre o SlopXLR.</p>');return;}$('navigation').innerHTML=nav();updateHeader();if(!mixer()||!ui.connected){$('main').innerHTML=ui.page==='settings'?heading(__tr('Preferências e configuração do dispositivo.'))+distributionSettings()+systemSettings(ui.status?.config||{}):renderDisconnected();return;}stopPreview();$('main').innerHTML=views[ui.page]();if(ui.page==='sampler')mountWave();if(ui.busy){$('main').querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);}if(focus)$(focus)?.focus();positionFeedback();}
function positionFeedback(){if(!$('application-form'))return;const slot=(Number($('binding-page').value)-1)*4+faders.indexOf($('binding-fader').value),channel=$('binding-channel').value,occupied=ui.apps.find((a,i)=>i!==ui.appEdit&&a.channel===channel&&a.slot===slot);$('position-feedback').textContent=occupied?(ui.adding?__tr`Posição ocupada por ${occupied.name}. Escolhe uma posição livre.`:__tr`Ao guardar esta edição, troca a posição com ${occupied.name}.`):__tr('Posição livre.');}
function layerConfig(data){return {enabled:data.enabled,pages:structuredClone(data.pages).map(p=>({...p,colours:p.colours||Array(6).fill('#009dff'),pressed_colours:p.pressed_colours||Array(6).fill('#ffffff')}))};}
export function applyAuxiliary(results){
 const [actions,apps]=results;
 ui.actionsError=actions.status==='rejected'?actions.reason.message||__tr('Leitura indisponível.'):'';
 ui.appsError=apps.status==='rejected'?apps.reason.message||__tr('Leitura indisponível.'):'';
 if(actions.status==='fulfilled'){ui.liveLayer=actions.value;const config=layerConfig(ui.liveLayer);if(!layerDirty()){ui.savedLayer=structuredClone(config);ui.layer=config;ui.actionPage=Math.min(ui.actionPage,ui.layer.pages.length-1);}}
 if(apps.status==='fulfilled'){ui.appLive=apps.value;if(!appsDirty()&&!ui.adding&&ui.appEdit===null){ui.savedApps=structuredClone(ui.appLive.applications);ui.apps=structuredClone(ui.savedApps);}}
}
function scheduleRefresh(){if(ui.stopped)return;if(polling||ui.busy){refreshPending=true;return;}if(!eventTimer)eventTimer=setTimeout(()=>{eventTimer=null;if(polling||ui.busy)refreshPending=true;else refresh();},50);}
function syncLiveValues(){if(ui.busy)return;
  const modeMessage=$('apps-mode-message');if(modeMessage){const message=ui.appLive?.runtime?.message||'';modeMessage.hidden=!message;modeMessage.textContent=message;}
 if(ui.page==='mixer'){for(const input of document.querySelectorAll('[data-volume]')){const c=input.dataset.volume,v=pct(mixer().levels.volumes[c]);if(input!==document.activeElement){input.value=v;$(input.id+'-value').textContent=v+'%';}const button=input.closest('.channel').querySelector('[data-mute]'),f=button.dataset.mute,muted=f&&mixer().fader_status[f]?.mute_state!==__tr('Unmuted');button.textContent=muted?__tr('Reativar som'):__tr('Silenciar');button.setAttribute('aria-pressed',String(Boolean(muted)));}for(const c of [__tr('Headphones'),__tr('LineOut'),__tr('MicMonitor')]){const input=$('out-'+c);if(input&&input!==document.activeElement){input.value=pct(mixer().levels.volumes[c]);$(input.id+'-value').textContent=input.value+'%';}}}
 if(ui.page==='apps'){const r=ui.appLive?.runtime,active=r?.active&&r.channel===ui.channel&&r.page+1===ui.appPage;for(const slot of document.querySelectorAll('[data-app-slot]')){const i=Number(slot.dataset.appSlot),a=ui.apps?.find(a=>a.channel===ui.channel&&a.slot===(ui.appPage-1)*4+i),note=slot.querySelector('small:last-child');if(note)note.textContent=active&&a?(r.pickup?.[i]?__tr`Move até ${r.volume?.[i]??a.reset_volume}% para ativar`:`${r.volume?.[i]??'—'}%${r.muted?.[i]?__tr(' · sem som'):''}`):__tr('Posição nesta página');}}
}
async function refresh(){if(polling||ui.busy||ui.stopped)return;polling=true;const wasConnected=ui.connected;try{
  const status=await request('/api/get-devices');if(ui.stopped)return;ui.status=status;if(!ui.serial)ui.serial=Object.keys(status.mixers||{})[0]||'';ui.connected=Boolean(mixer());ui.serviceError='';
  if(ui.connected&&isMini(mixer())){const results=await Promise.allSettled([request(devicePath('button-actions',ui.serial)),request(devicePath('application-controls',ui.serial))]);applyAuxiliary(results);}
  else if(ui.connected){ui.liveLayer=null;ui.appLive=null;ui.actionsError=ui.appsError='';}
  updateReadErrors();
  if(ui.connected)syncLiveValues();
  updateHeader();const next=JSON.stringify([mixer(),ui.liveLayer,ui.appLive,ui.status.config,ui.status.files,ui.status.firmware]);const editing=ui.recording||document.activeElement?.matches('input,select,textarea,button')||Boolean($('application-form'))||Boolean(library.clip)||Boolean($('stop-confirmation'))||Boolean($('sample-preview')&&!$('sample-preview').paused);if(wasConnected!==ui.connected||(next!==signature&&!editing)){signature=next;render();}
}catch(error){if(ui.stopped)return;ui.connected=false;ui.serviceError=error.message;updateHeader();render();}finally{polling=false;if(refreshPending){refreshPending=false;scheduleRefresh();}}}
async function write(work,success){if(ui.busy||!ui.connected){notify(__tr('Aguarda a ligação ao dispositivo.'),true);return;}ui.busy=true;ui.recording=false;render();try{await work();notify(success);}catch(error){notify(error.message||__tr('A operação não foi concluída.'),true);}finally{ui.busy=false;await refresh();render();}}
async function save(kind){const serial=ui.serial;if(kind==='actions'?ui.actionsError:ui.appsError)throw new Error(__tr('Aguarda a atualização das configurações antes de guardar.'));if(kind==='actions'){validateLayer(ui.layer,ui.status.files.profiles||[]);const submitted=structuredClone(ui.layer);await write(async()=>{const remote=layerConfig(await request(devicePath('button-actions',serial)));if(dirty(remote,ui.savedLayer))throw new Error(__tr('As ações foram alteradas noutra janela. Copia as tuas alterações antes de repor e voltar a editar.'));await request(devicePath('button-actions',serial),{method:__tr('POST'),body:submitted});ui.savedLayer=submitted;ui.undo=null;},__tr('Ações guardadas.'));}else{const submitted=structuredClone(ui.apps);await write(async()=>{const remote=await request(devicePath('application-controls',serial));if(dirty(remote.applications,ui.savedApps))throw new Error(__tr('As aplicações foram alteradas noutra janela. Copia as tuas alterações antes de repor e voltar a editar.'));await request(devicePath('application-controls',serial),{method:__tr('POST'),body:submitted});ui.savedApps=submitted;ui.undo=null;},__tr('Aplicações guardadas. O modo de aplicações foi fechado; o encaminhamento será verificado pelo serviço.'));}}
function replaceValues(value,input){if(Array.isArray(value))return value.map(v=>replaceValues(v,input));if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,replaceValues(v,input)]));return value==='$nullable'?(input.value||null):value==='$hold'?input.value==='hold':value==='$value'?input.value:value==='$number'?(input.hasAttribute('data-reverb-decay')?reverbDecayValues[Number(input.value)]:Number(input.value)):value==='$volume'?volume(input.value):value==='$checked'?input.checked:value;}
